with ev as (
 select issue_key, occurred_at, recorded_at, payload->>'status' st from events where type='issue.created' and recorded_at<=TIMESTAMP '2012-07-31 16:19' and occurred_at<=TIMESTAMP '2012-07-31 05:03'
 union all
 select issue_key, occurred_at, recorded_at, payload->>'status' from events where type='issue.status_changed' and recorded_at<=TIMESTAMP '2012-07-31 16:19' and occurred_at<=TIMESTAMP '2012-07-31 05:03'
), d as (
 select *, row_number() over (partition by issue_key, occurred_at order by recorded_at desc) rn from ev
), l as (
 select *, row_number() over (partition by issue_key order by occurred_at desc, recorded_at desc) r2 from d where rn=1
)
select st, count(*) from l where r2=1 group by st
